<template><Teleport to="body"><div class="drawer-backdrop" @click.self="$emit('close')" @keydown.esc="$emit('close')"><section ref="dialog" class="drawer" role="dialog" aria-modal="true" aria-labelledby="record-title" tabindex="-1"><header class="drawer-head"><div><p class="eyebrow">RECORD DETAIL</p><h2 id="record-title">记录详情</h2></div><button class="icon-button" aria-label="关闭详情" @click="$emit('close')">×</button></header><div class="drawer-body"><div v-if="error" class="error-box" role="alert">{{error}}</div><div v-if="loading" class="empty">正在读取记录…</div><template v-else-if="detail"><div class="actions"><span class="tag purple">{{kindNames[record.kind]}}</span><span class="tag" :class="record.confirmation==='pending'?'amber':''">{{stateNames[record.confirmation]}}</span><span class="subtle tiny">{{record.date}}</span></div><h3 style="font-size:18px;margin-top:15px;line-height:1.6">{{record.description}}</h3><div class="metric-value" :class="{refund:record.kind==='refund'}">{{record.kind==='refund'?'−':''}}{{amount(record.cents,record.currency,show)}}</div><p class="subtitle">{{record.accountName||'未关联账户'}} · {{record.channel}}</p><div class="drawer-section"><h3>分类与说明</h3><div class="form-grid"><label class="field">消费分类<select v-model="draft.category" class="control"><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label class="field">标签（逗号分隔）<input v-model="tags" class="control"/></label></div><label class="field" style="margin-top:14px">核对说明<textarea v-model="draft.note" class="control" rows="3" placeholder="记录调整原因或核对结论"/></label><label class="actions subtitle"><input v-model="draft.reviewed" type="checkbox"/>分类已人工核实</label><p v-if="record.note" class="subtitle" style="white-space:pre-wrap">来源说明：{{record.note}}</p></div>
<div v-if="record.kind==='refund'||record.kind==='receipt'" class="drawer-section"><h3>{{record.kind==='refund'?'退款分配与确认':'凭证关联'}}</h3><p class="subtitle">{{record.relationStatus||'尚未确认关联'}}。候选仅供核对，关联不会新增消费。</p><div v-for="(a,i) in draft.allocations" :key="i" class="actions" style="margin-top:10px"><input v-model="a.key" class="control" style="flex:1;min-width:0" placeholder="消费记录标识"/><input v-if="record.kind==='refund'" :value="a.cents/100" type="number" min="0.01" step="0.01" class="control" style="width:100px" @input="a.cents=Math.round(Number(($event.target as HTMLInputElement).value)*100)"/><button class="icon-button" aria-label="移除关联" @click="draft.allocations.splice(i,1)">×</button></div><button class="button ghost" @click="draft.allocations.push({key:'',cents:record.kind==='refund'?record.cents||0:0})">＋ 添加关联</button><p v-if="detail.candidates.length" class="subtitle">可能匹配的消费（{{detail.candidates.length}}）</p><div v-for="c in detail.candidates.slice(0,12)" :key="c.key" class="insight-row"><div style="min-width:0"><p>{{c.date}} · {{c.merchant}}</p><p class="subtitle">{{amount(c.cents,c.currency,show)}}</p></div><button class="button" @click="addCandidate(c)">选择</button></div><label class="actions subtitle"><input v-model="draft.relationReviewed" type="checkbox"/>我已核对关联及退款分配</label></div>
<div v-if="record.kind==='schedule'" class="drawer-section"><h3>还款状态</h3><select v-model="draft.status" class="control"><option v-for="k in ['estimated','billed','paid','cancelled','replaced']" :key="k" :value="k">{{stateNames[k]}}</option></select><label v-if="draft.status==='replaced'" class="field" style="margin-top:12px">替代它的正式账单或已出账事项<select v-model="draft.replacedBy" class="control"><option value="">选择同账户的正式账单</option><option v-for="candidate in detail?.candidates" :key="candidate.key" :value="candidate.key">{{candidate.date}} · {{candidate.description}} · {{amount(candidate.cents,candidate.currency,show)}}</option></select></label><p class="subtitle">标记已还仅记录核实结果，不会再次计入消费或自动扣减账户余额。未确认状态不用于判断逾期。</p></div>
<div class="drawer-section"><h3>关联记录</h3><div v-if="!detail.related.length" class="subtitle">暂无关联记录</div><button v-for="r in detail.related" :key="r.key" class="insight-row" style="width:100%;text-align:left;background:white" @click="$emit('open',r.key)"><span>{{kindNames[r.kind]}} · {{r.date}}<p class="subtitle">{{r.description}}</p></span><span>{{amount(r.cents,r.currency,show)}} →</span></button></div>
<div class="drawer-section"><h3>凭证附件</h3><div v-for="a in detail.attachments" :key="a.id" class="insight-row"><span>{{a.name}}<p class="subtitle">{{(a.size/1024).toFixed(1)}} KB</p></span><button class="button" @click="viewAttachment(a.id)">查看</button></div><label class="button" style="margin-top:12px">上传 PDF / 图片<input type="file" accept="application/pdf,image/png,image/jpeg" style="max-width:170px" @change="upload" :disabled="saving"/></label></div><details v-if="record.metadata" class="drawer-section"><summary style="font-size:12px;cursor:pointer">完整来源字段（订单、商品与账单信息）</summary><dl class="detail-grid metadata" style="margin-top:14px"><template v-for="(value,key) in record.metadata" :key="key"><dt>{{key}}</dt><dd>{{formatMeta(value)}}</dd></template></dl></details><div class="drawer-section"><h3>处理历史</h3><p v-if="!detail.history.length" class="subtitle">尚未人工修改</p><div v-for="h in detail.history" :key="h.id" class="insight-row"><span>{{h.reason}}<p class="subtitle">{{new Date(h.createdAt).toLocaleString('zh-CN')}}</p></span><button class="button ghost" @click="restore(h.before)">恢复此前值</button></div></div><p class="subtitle source-link">记录标识：{{record.key}} · 版本 {{record.version}}</p></template></div><footer v-if="detail" class="drawer-footer"><button class="button primary" :disabled="saving" @click="save">{{saving?'正在保存…':'保存核对结果'}}</button><button class="button" @click="$emit('close')">关闭</button></footer></section></div></Teleport></template>
<script setup lang="ts">
import {ref,computed,watch,onMounted,onBeforeUnmount,nextTick} from 'vue'
import {getDetail,saveEdits,amount,kindNames,stateNames,blankEdit} from '@/api/workspace'
import type {Category,Detail,Edit,Entry} from '@/api/workspace'
const props=defineProps<{recordKey:string;categories:Category[];show:boolean}>()
const emit=defineEmits<{(e:'close'):void;(e:'saved'):void;(e:'open',key:string):void}>()
const detail=ref<Detail|null>(null),loading=ref(false),saving=ref(false),error=ref(''),tags=ref(''),dialog=ref<HTMLElement|null>(null)
const draft=ref<Edit>(blankEdit()),record=computed(()=>detail.value!.record)
let sequence=0;const previousFocus=document.activeElement as HTMLElement|null
watch(()=>props.recordKey,async key=>{const seq=++sequence;loading.value=true;detail.value=null;error.value='';try{const d=await getDetail(key);if(seq!==sequence)return;detail.value=d;draft.value={...blankEdit(),...d.record.edit,category:d.record.category,allocations:d.record.edit.allocations?.map(a=>({...a}))||[],relatedKeys:[...(d.record.edit.relatedKeys||[])]};if(d.record.kind==='receipt'&&!draft.value.allocations.length)draft.value.allocations=d.record.relatedKeys.map(key=>({key,cents:0}));tags.value=d.record.tags.join('，')}catch(e){if(seq===sequence)error.value=String(e)}finally{if(seq===sequence)loading.value=false}},{immediate:true})
function formatMeta(v:unknown){if(v===null||v===undefined)return '—';return typeof v==='object'?JSON.stringify(v):String(v)}
function addCandidate(c:Entry){if(!draft.value.allocations.some(a=>a.key===c.key))draft.value.allocations.push({key:c.key,cents:record.value.kind==='refund'?record.value.cents||0:0})}
function restore(before:string){draft.value={...blankEdit(),...(before?JSON.parse(before):{})};draft.value.allocations=draft.value.allocations||[];tags.value=draft.value.tags?.join('，')||''}
async function save(){if(!detail.value||loading.value||saving.value)return;saving.value=true;error.value='';try{const edit={...draft.value,tags:tags.value.split(/[,，]/).map(x=>x.trim()).filter(Boolean)};if(edit.relationReviewed)edit.relatedKeys=edit.allocations.map(a=>a.key);await saveEdits([{key:record.value.key,version:record.value.version,edit}],'人工核对：'+(edit.note||'分类、关联或还款状态'));emit('saved');emit('close')}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{saving.value=false}}
function trap(e:KeyboardEvent){if(e.key!=='Tab'||!dialog.value)return;const nodes=[...dialog.value.querySelectorAll<HTMLElement>('button:not(:disabled),input,select,textarea,summary,[tabindex="0"]')];const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}
onMounted(async()=>{await nextTick();dialog.value?.focus();dialog.value?.addEventListener('keydown',trap)})
async function upload(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;saving.value=true;error.value='';try{const form=new FormData();form.append('file',file);form.append('key',record.value.key);const r=await fetch('/api/workspace/attachments',{method:'POST',headers:{Authorization:'Bearer '+localStorage.getItem('access_token')},body:form});const body=await r.json();if(!r.ok||body.code!==0)throw Error(body.message||'上传失败');detail.value?.attachments.push(body.data)}catch(e){error.value=String(e)}finally{saving.value=false}}
const attachmentURLs:string[]=[]
async function viewAttachment(id:string){try{const r=await fetch('/api/workspace/attachments/'+encodeURIComponent(id),{headers:{Authorization:'Bearer '+localStorage.getItem('access_token')}});if(!r.ok)throw Error('读取附件失败');const url=URL.createObjectURL(await r.blob());attachmentURLs.push(url);window.open(url,'_blank','noopener')}catch(e){error.value=String(e)}}
onBeforeUnmount(()=>{attachmentURLs.forEach(u=>URL.revokeObjectURL(u));sequence++;dialog.value?.removeEventListener('keydown',trap);previousFocus?.focus()})
</script>
